def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 20.0))

    units_available = int(supply // WATER_REQ)
    if units_available < 1:
        units_available = 1

    opp_bids = []
    urgent_opp = 0
    rich_opp = 0
    max_prev_bid = 0.0
    sum_prev_bid = 0.0
    count_prev = 0

    for opp in alive:
        if opp.get('budget', 0) >= 350:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            opp_bids.append(float(bid))
            sum_prev_bid += float(bid)
            count_prev += 1
            if float(bid) > max_prev_bid:
                max_prev_bid = float(bid)

    avg_prev_bid = (sum_prev_bid / count_prev) if count_prev > 0 else 55.0

    scarcity = 0
    if units_available <= 1:
        scarcity = 2
    elif units_available == 2:
        scarcity = 1

    my_urgent = False
    if hp <= 3 or no_water >= 1:
        my_urgent = True

    if my_urgent:
        target = max(82.0, max_prev_bid + 2.5)
        if scarcity >= 2:
            target = max(target, 96.0)
        elif scarcity == 1:
            target = max(target, 86.0)
        return float(min(budget, target))

    if hp >= 8 and no_water == 0:
        if max_prev_bid >= 90.0 and scarcity >= 1:
            return float(min(budget, 24.0))
        if scarcity >= 2:
            return float(min(budget, 41.0))
        return float(min(budget, 18.0))

    target = avg_prev_bid + 1.6
    if max_prev_bid >= 100.0:
        target = min(target, 62.0)
    elif max_prev_bid >= 85.0:
        target = min(target, 58.0)

    if scarcity >= 2:
        target += 10.0
    elif scarcity == 1:
        target += 4.0

    if urgent_opp >= 2:
        target += 6.0
    elif urgent_opp == 0 and max_prev_bid >= 85.0:
        target -= 6.0

    if rich_opp >= 3 and scarcity >= 1:
        target += 4.0

    if day >= 8 and hp <= 5:
        target += 10.0

    if hp <= 5:
        target = max(target, 64.0)
    else:
        target = max(target, 36.0)

    if budget < 120:
        target = min(target, budget)
    else:
        target = min(target, 92.0)

    if target < 0:
        target = 0.0

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    # Use yesterday's meta-round averages as prior knowledge
    avg_bids = {'Alex': 45.22, 'Bob': 57.57, 'Cindy': 64.97, 'David': 53.6}
    # Combine with previous_trace if available
    for opp_id, opp in opponents_status.items():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            avg_bids[opp_id] = prev['bid']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    # Compute max expected bid from opponents
    expected_bids = [avg_bids.get(opp_id, DAILY_SALARY * 0.6) for opp_id in opponents_status if opponents_status[opp_id]['alive']]
    max_expected = max(expected_bids) if expected_bids else 0
    # My target bid: slightly above max expected, but moderate
    target = max(max_expected + 2, DAILY_SALARY * 0.5)
    # Adjust if my HP is low
    if my_status['hp'] <= 2:
        target = max(target, DAILY_SALARY * 0.9)
    # Ensure we don't overspend budget
    bid = min(my_status['budget'], target)
    # Ensure positive
    return max(0, bid)
